 * @param {string} url - The initially detected (possibly truncated) URL
 * @param {string} line - The full line of text containing the URL
 * @param {number} lastIndex - End position (exclusive) of the URL match in the line
 * @returns {{ url: string }} Object whose `url` property holds the extended URL
