function extendUrlWithBalancedParentheses(url, line, lastIndex) {
  let openCount = 0;
  let closeCount = 0;
  for (let i = 0; i < url.length; i++) {
    if (url[i] === '(') openCount++;
    else if (url[i] === ')') closeCount++;
  }

  // Already balanced (or over-balanced): nothing to extend.
  if (openCount <= closeCount) {
    return { url };
  }

  let extended = url;
  let i = lastIndex;
  while (i < line.length && openCount > closeCount) {
    const ch = line[i];

    // Stop at whitespace; anything after it is not part of the URL.
    if (/\s/.test(ch)) break;

    if (ch === ')') {
      // Don't append a closing paren that would over-balance the URL.
      if (closeCount + 1 > openCount) break;
      closeCount++;
    } else if (ch === '(') {
      openCount++;
    }

    extended += ch;
    i++;
